import pandas as pd


def _differs(a, b):
    """NULL vs NULL -> not differing; NULL vs non-NULL -> differing;
    otherwise plain inequality."""
    a_null = pd.isna(a)
    b_null = pd.isna(b)
    if a_null and b_null:
        return False
    if a_null or b_null:
        return True
    return a != b


def run(inputs):
    dim_store = inputs["DIM_STORE"].copy()
    stg_store_full = inputs["STG_STORE_FULL"].copy()
    batch_control = inputs["BATCH_CONTROL"].copy()

    # exactly one row expected
    b = batch_control["batch_date"].iloc[0]

    # DISTINCT store_id, region, format from the staging snapshot
    S = stg_store_full.drop_duplicates(
        subset=["store_id", "region", "format"]
    )[["store_id", "region", "format"]].reset_index(drop=True)

    result = dim_store.copy()

    # map store_id -> index of its current (is_current == 1) row, if any
    current_by_store = {}
    for idx, row in result.loc[result["is_current"] == 1].iterrows():
        current_by_store[row["store_id"]] = idx

    new_rows = []
    s_store_ids = set()

    for _, s in S.iterrows():
        store_id = s["store_id"]
        s_store_ids.add(store_id)

        if store_id in current_by_store:
            idx = current_by_store[store_id]
            c = result.loc[idx]
            if _differs(c["region"], s["region"]) or _differs(c["format"], s["format"]):
                # close current, open new version
                result.at[idx, "eff_end_date"] = b
                result.at[idx, "is_current"] = 0
                new_rows.append(
                    {
                        "store_id": store_id,
                        "region": s["region"],
                        "format": s["format"],
                        "eff_start_date": b,
                        "eff_end_date": pd.NaT,
                        "is_current": 1,
                    }
                )
            # else: attributes match -> no-op
        else:
            # no current row: new store or reopened store -> always new version
            new_rows.append(
                {
                    "store_id": store_id,
                    "region": s["region"],
                    "format": s["format"],
                    "eff_start_date": b,
                    "eff_end_date": pd.NaT,
                    "is_current": 1,
                }
            )

    # close current rows whose store_id is not present in the snapshot at all
    for store_id, idx in current_by_store.items():
        if store_id not in s_store_ids:
            result.at[idx, "eff_end_date"] = b
            result.at[idx, "is_current"] = 0

    if new_rows:
        new_df = pd.DataFrame(new_rows)
        result = pd.concat([result, new_df], ignore_index=True, sort=False)

    result = result[
        ["store_id", "region", "format", "eff_start_date", "eff_end_date", "is_current"]
    ].reset_index(drop=True)

    return {"dim_store_out": result}
